def max_herb_value(T, M, herbs):
    # Initialize a 2D array to store the maximum value of herbs that can be picked
    # within the time limit, considering all possible combinations of herbs
    dp = [[0] * (M + 1) for _ in range(T + 1)]

    # Base case: when there are no herbs or time limit is 0, the maximum value is 0
    for i in range(M + 1):
        dp[0][i] = 0

    # Populate the array with the values of the herbs and the time constraints
    for t in range(1, T + 1):
        for m in range(1, M + 1):
            time, value = herbs[m - 1]
            if time <= t:
                dp[t][m] = max(dp[t - time][m - 1] + value, dp[t][m - 1])
            else:
                dp[t][m] = dp[t][m - 1]

    # Return the maximum value that can be picked within the time limit
    return dp[T][M]
```

