def min_remaining_space(V, n, volumes):
    # Initialize a 2D array to store the results of sub-problems
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Base case: when there are no items or the box is empty
    for i in range(V + 1):
        dp[i][0] = 0

    # Fill dp table in a bottom-up manner using the recurrence relation
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            if volumes[j - 1] > i:
                dp[i][j] = dp[i][j - 1]
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i - volumes[j - 1]][j - 1])

    # Return the minimum remaining space
    return V - dp[V][n]
